<?php
declare(strict_types=1);
require_once __DIR__.'/includes/init.php';require_once __DIR__.'/csrf_helper.php';require_once __DIR__.'/includes/shop_checkout.php';
if(!isset($_SESSION['trener_id'])||!roleAtLeast('admin')){header('Location: login.php');exit;}
function orderAdminH(mixed $value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function orderAdminMoney(int $minor,string $currency):string{return number_format($minor/100,2,',',' ').' '.orderAdminH($currency);}
$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!csrf_verify((string)($_POST['csrf_token']??'')))$errors[]='Formulář vypršel. Obnovte stránku.';
    else try{$result=shopOrderAdminConfirmBankPayment($pdo,(int)($_POST['payment_id']??0),(int)$_SESSION['trener_id'],(string)($_POST['reason']??''),($_POST['confirm_payment']??'')==='1');$_SESSION['flash_order_admin']=$result['changed']?'Bankovní platba byla potvrzena a objednávka přešla do zpracování.':'Platba už byla potvrzena.';header('Location: eshop_orders_admin.php',true,303);exit;}
    catch(PDOException $exception){error_log('eshop_orders_admin.php: '.$exception->getMessage());$errors[]='Databázová operace selhala bez částečného zápisu.';}
    catch(InvalidArgumentException|ShopCheckoutException $exception){$errors[]=$exception->getMessage();}
}
$success=(string)($_SESSION['flash_order_admin']??'');unset($_SESSION['flash_order_admin']);$orders=shopOrderAdminList($pdo);
?>
<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Objednávky K4</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"></head><body class="bg-light"><?php include __DIR__.'/hlavicka.php';?><main class="container-fluid py-4" style="max-width:1450px"><div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h4 mb-0"><i class="bi bi-receipt me-2 text-primary"></i>Objednávky K4</h1><div class="small text-muted">První vertikála: osobní odběr a ručně potvrzený bankovní převod.</div></div><a href="eshop_admin.php" class="btn btn-outline-secondary btn-sm">Administrace e-shopu</a></div><?php foreach($errors as$error):?><div class="alert alert-danger"><?=orderAdminH($error)?></div><?php endforeach;?><?php if($success!==''):?><div class="alert alert-success"><?=orderAdminH($success)?></div><?php endif;?><div class="alert alert-warning small">Potvrzení znamená, že administrátor skutečně ověřil příchozí platbu v bance. Návrat zákazníka ani QR kód stav platby nemění.</div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Objednávka</th><th>Zákazník</th><th>Částka</th><th>VS</th><th>Objednávka</th><th>Platba</th><th>Akce</th></tr></thead><tbody><?php foreach($orders as$order):?><tr><td><code><?=orderAdminH($order['public_code'])?></code><div class="small text-muted"><?=orderAdminH($order['created_at'])?></div></td><td><?=orderAdminH($order['customer_name_snapshot'])?><div class="small"><?=orderAdminH($order['customer_email_snapshot'])?></div></td><td><?=orderAdminMoney((int)$order['total_minor'],(string)$order['currency'])?></td><td><code><?=orderAdminH($order['variable_symbol'])?></code></td><td><?=orderAdminH($order['status'])?></td><td><span class="badge text-bg-<?=$order['payment_record_status']==='paid'?'success':'warning'?>"><?=orderAdminH($order['payment_record_status'])?></span></td><td><?php if($order['payment_record_status']==='pending'):?><form method="post" class="d-flex flex-column gap-1" style="min-width:260px"><?=csrf_field()?><input type="hidden" name="payment_id" value="<?=(int)$order['payment_id']?>"><input class="form-control form-control-sm" name="reason" maxlength="1000" required placeholder="Jak byla platba ověřena"><label class="small"><input type="checkbox" name="confirm_payment" value="1" required> Potvrzuji přijetí v bance</label><button class="btn btn-sm btn-outline-success">Označit jako zaplacené</button></form><?php else:?><span class="small text-muted">Potvrzeno <?=orderAdminH($order['paid_at'])?></span><?php endif;?></td></tr><?php endforeach;?><?php if($orders===[]):?><tr><td colspan="7" class="text-center text-muted py-4">Zatím není žádná objednávka.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>
